import sys,json,subprocess,time,hashlib,datetime,re,concurrent.futures
from pathlib import Path
ROOT=Path(__file__).parent
A=json.loads((ROOT/'aud02.json').read_text());M=json.loads((ROOT/'m7.json').read_text())
PREFIX='fridadev-m7-conc-fix'
def adapt(argv):
 result=[]
 for a in argv:
  for old in ['/tmp/fridadev-m8c-aud02-20261009','/tmp/fridadev-m8c-aud01-20261007','/tmp/fridadev-m7-proof-20261007']:a=a.replace(old,str(ROOT))
  for old in ['fridadev-m7-proof','fridadev-m8c-aud01','fridadev-m8c-aud02']:a=a.replace(old,PREFIX)
  a=a.replace(PREFIX+'-pg-20261007',PREFIX+'-pg-20261009').replace(PREFIX+'-vector-20261007',PREFIX+'-vector-20261009');result.append(a)
 return result
SELECTIONS=dict(A['final']['selections']);SELECTIONS.update(renderer=A['final']['M8C_historical_AUD01'],aud02=A['final']['new_selection'])
def record(label,argv):
 t=time.monotonic();started=datetime.datetime.now(datetime.timezone.utc).isoformat()
 p=subprocess.run(argv,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);out=p.stdout.decode(errors='replace');(ROOT/(label+'.log')).write_bytes(p.stdout)
 r=dict(label=label,argv=argv,started_utc=started,wall_seconds=round(time.monotonic()-t,3),exit=p.returncode,log_sha256=hashlib.sha256(p.stdout).hexdigest(),log_bytes=len(p.stdout),source_test_sha256=hashlib.sha256(Path('app/tests/integration/document_workshop/test_update_m7_postgresql.py').read_bytes()).hexdigest())
 if 'unittest' in argv or re.search(r'Ran (\d+) tests? in ([\d.]+)s',out):
  r['test_ids']=re.findall(r'^test\S* \(([^)]+)\) \.\.\. ',out,re.M);m=re.search(r'Ran (\d+) tests? in ([\d.]+)s',out);r['tests']=int(m[1]) if m else None
  tail=out[out.rfind('Ran '):]
  for k in ['errors','failures','skipped']:
   m=re.search(k+r'=(\d+)',tail);r[k]=int(m[1]) if m else 0
  r['unsuccessful_ids']=re.findall(r'^(?:FAIL|ERROR): (test.*)$',out,re.M)
 elif '--test' in argv:
  r['test_names']=re.findall(r'^# Subtest: (.*)$',out,re.M)
  for k in ['tests','pass','fail','skipped','cancelled']:
   m=re.search(r'^# '+k+r' (\d+)$',out,re.M);r[k]=int(m[1]) if m else None
  r['unsuccessful_names']=re.findall(r'^not ok \d+ - (.*)$',out,re.M)
 (ROOT/(label+'.json')).write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items() if k not in ['argv','test_ids','test_names']}),flush=True)
 if p.returncode:print(out[-2500:],flush=True)
 return p.returncode

def py(label,args):
 argv=adapt(A['final']['new_selection']['argv']);i=argv.index('python');return record(label,argv[:i]+['python',*args])
def setup():
 for key in ['setup-pg','setup-vector','http-pg-start-good','native-pg-start']:
  argv=adapt(M['isolation']['setup_records'][key]['argv'])
  for arg in argv:
   if arg.endswith(':/var/run/postgresql'):Path(arg.split(':')[0]).mkdir(exist_ok=True)
  assert record(key,argv)==0
  name=argv[argv.index('--name')+1]
  for _ in range(100):
   if subprocess.run(['docker','exec',name,'pg_isready','-U','m1proof'],capture_output=True).returncode==0:break
   time.sleep(.1)
  else:raise RuntimeError('owned PG readiness timeout')
def native(epoch,kind):
 key='final-v4-http-start' if kind=='m6' else 'final-m7-native-v4-http-start'
 argv=adapt(M['isolation']['setup_records'][key]['argv']);name=argv[argv.index('--name')+1]
 marker=ROOT/('http-ready' if kind=='m6' else 'native/http-ready');marker.parent.mkdir(exist_ok=True);marker.unlink(missing_ok=True)
 exists=subprocess.check_output(['docker','ps','-a','--filter','name=^/'+name+'$','--format','{{.Names}}']).decode().strip()
 if exists:assert record(epoch+'-'+kind+'-previous-remove',['docker','rm','-f',name])==0
 assert record(epoch+'-'+kind+'-start',argv)==0
 for _ in range(600):
  if marker.exists():break
  time.sleep(.05)
 else:raise RuntimeError('owned HTTP readiness timeout')
 selection='browser-native-http' if kind=='m6' else 'm7-native-http'
 return record(epoch+'-'+selection,adapt(SELECTIONS[selection]['argv']))
def compare(epoch):
 batches=[['final-baseline-python','final-new-python','lane-unit'],['final-baseline-node','final-baseline-chromium_historical','final-baseline-chromium_m4','final-new-browser','browser-simulated'],['final-baseline-sql','final-new-sql','product-sql','new-pause-sql','m7-python','renderer','aud02'],['final-baseline-vector']]
 def group(keys):
  for key in keys:record(epoch+'-'+key,adapt(SELECTIONS[key]['argv']))
 with concurrent.futures.ThreadPoolExecutor(4) as pool:list(pool.map(group,batches))
 native(epoch,'m6');native(epoch,'m7')
 record(epoch+'-neighbors70',adapt(A['final']['neighbors70']['argv']))
 record(epoch+'-exports-readers26',adapt(A['final']['exports_readers26']['argv']))
if __name__=='__main__':
 mode=sys.argv[1]
 if mode=='setup':setup()
 elif mode=='compare':compare(sys.argv[2])
 elif mode=='py':sys.exit(py(sys.argv[2],sys.argv[3:]))

